// === Tab: mySketch ===
const vs = `
attribute vec3 aPosition;
attribute vec4 aMaterialColor;

uniform mat4 uModelViewMatrix;
uniform mat4 uProjectionMatrix;

varying vec4 vColor;

void main(void) {
   gl_Position = uProjectionMatrix * uModelViewMatrix * vec4(aPosition, 1.0);
	 vColor = aMaterialColor;
}
`;

const fs = `
precision highp float;

varying vec4 vColor;

void main(void) {
   gl_FragColor = vColor;
}
`;

const w = 1112;
const fps = 1;
const N = 7;
const l = w/4;
let theShader;

function setup() {
   createCanvas(w, w*.75, WEBGL);
   frameRate(fps);
   colorMode(HSB);

   theShader = createShader(vs, fs);
   shader(theShader);
}

function draw() {
   background(0);

   for (let i=0; i<N; i++) {
      let th = [-1+2/N*(i), -1+2/N*(i+1)];
      push();
      rotateX(frameCount/37);
      rotateZ(-frameCount/49);
      translate(l/2*sin(TAU/N * (int(frameCount/3)%N) + i),
               -l/4 * (i - N/2 + 0.5) * max(sin(frameCount/27), -0.125),
               0);
      divided_sphere(l, 64, 64, th, [(360/N*i*2)%360, 70, 100]);
      pop();
   }
}

function divided_sphere(size, detailX, detailY, th, color) {
   const gId = `divided_sphere|${size}|${detailX}|${detailY}|${th}`;

   if (!this._renderer.geometryInHash(gId)) {
      const geom = new p5.Geometry(detailX, detailY);

      for (let i=0; i<=detailX; i++) {
         let v = i / detailX;
         let phi = PI * v - HALF_PI;

         let phi_th = [Math.acos(th[0])-PI/2, Math.acos(th[1])-PI/2];
         let newphi = (phi <= phi_th[1]) ? phi_th[1] : 
                      (phi >= phi_th[0]) ? phi_th[0] : phi;

         let sinPhi = sin(newphi);
         let cosPhi = cos(newphi);

         cosPhi = (phi <= phi_th[1]) ? 0 :
                  (phi >= phi_th[0]) ? 0 : cosPhi;

         for (let j=0; j<=detailY; j++) {
            let u = j / detailY;
            let theta = TWO_PI * u;
            let sinTheta = sin(theta);
            let cosTheta = cos(theta);

            let p = new p5.Vector(
               cosPhi * sinTheta,
               sinPhi,
               cosPhi * cosTheta);
            geom.vertices.push(p);
            geom.vertexNormals.push(p);
            geom.uvs.push(u, v);

					 let color_set = sin((j-detailX/2)/5+(i-detailY/2)/10)*0.1 + 1.0 ;
           geom.vertexColors.push(
            (red(color)   * color_set) / 255,
            (green(color) * color_set) / 255,
            (blue(color)  * color_set) / 255,
            1);
         }
      }
      geom.computeFaces();
      geom._makeTriangleEdges()._edgesToVertices();
      this._renderer.createBuffers(gId, geom);
   }
   this._renderer.drawBuffersScaled(gId, size, size, size);
}

// save jpg
let lapse = 0;    // mouse timer
function mousePressed(){
  if (millis() - lapse > 400){
    save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg");
    lapse = millis();
  } 
}

